import { randomUUID } from 'crypto';
import { and, eq, lte } from 'drizzle-orm';
import {
  closeDatabase,
  openDurableDatabaseSync,
  transaction,
} from './database';
import { BROWSER_AUTHORIZATION_SCHEMA } from './migrations';
import {
  browserAuthority,
  browserCredentials,
} from './schema/browserAuthorization';

export interface AuthorizationSnapshot {
  accountId: string | null;
  generation: string;
}

interface AccountMutation {
  read: () => string | null;
  next: () => string | null;
  write: () => void;
  isLogout?: boolean;
  expectedGeneration?: string;
  isRecovery?: boolean;
  isIdentityEnrichment?: () => boolean;
}

interface CredentialInput {
  scope: string;
  digest: string;
  kind: 'session' | 'launch';
  expiresAt: number;
  now: number;
  readIdentity: () => string | null;
  expectedGeneration?: string;
}

interface CredentialLookup {
  scope: string;
  digest: string;
  now: number;
  readIdentity: () => string | null;
}

const AUTHORITY_SINGLETON = 1;

export class AuthorizationUnavailable extends Error {
  constructor() {
    super(
      'Browser authorization is temporarily unavailable. Sign in again or retry.',
    );
  }
}

export class AuthorizationChanged extends Error {
  constructor() {
    super('Rivet account changed during sign-in. Please try again.');
  }
}

export class BrowserAuthorizationRecords {
  private readonly db: ReturnType<typeof openDurableDatabaseSync>;

  constructor(databasePath: string) {
    this.db = openDurableDatabaseSync({
      databasePath,
      schema: BROWSER_AUTHORIZATION_SCHEMA,
    });
  }

  private authority(accountId: string | null) {
    const record = this.db.select().from(browserAuthority).get();
    if (record) return record;
    const initial = {
      singleton: AUTHORITY_SINGLETON,
      accountId,
      generation: randomUUID(),
      operationId: null,
      phase: 'ready' as const,
    };
    this.db.insert(browserAuthority).values(initial).run();
    return initial;
  }

  private requireAccount(accountId: string | null): AuthorizationSnapshot {
    const authority = this.authority(accountId);
    if (authority.phase !== 'ready' || authority.accountId !== accountId)
      throw new AuthorizationUnavailable();
    return { accountId, generation: authority.generation };
  }

  snapshot(readIdentity: () => string | null): AuthorizationSnapshot {
    return transaction(this.db, () => this.requireAccount(readIdentity()));
  }

  signInGeneration(readIdentity: () => string | null): string {
    return transaction(
      this.db,
      () => this.authority(readIdentity()).generation,
    );
  }

  mutateAccount(input: AccountMutation): AuthorizationSnapshot {
    const reserved = transaction(this.db, () => {
      const accountId = input.read();
      const authority = this.authority(accountId);
      if (
        input.expectedGeneration !== undefined &&
        ((!input.isRecovery &&
          (authority.phase !== 'ready' || authority.accountId !== accountId)) ||
          authority.generation !== input.expectedGeneration)
      )
        throw new AuthorizationChanged();
      const nextAccountId = input.next();
      const mustRevoke =
        input.isLogout ||
        authority.accountId !== accountId ||
        (accountId !== nextAccountId && !input.isIdentityEnrichment?.());
      const reservation = {
        accountId: nextAccountId,
        generation: mustRevoke ? randomUUID() : authority.generation,
        operationId: randomUUID(),
        phase: 'changing' as const,
      };
      this.db.update(browserAuthority).set(reservation).run();
      return reservation;
    });
    return transaction(this.db, () => {
      const authority = this.db.select().from(browserAuthority).get();
      if (authority?.operationId !== reserved.operationId)
        throw new AuthorizationChanged();
      input.write();
      this.db
        .update(browserCredentials)
        .set({ accountId: reserved.accountId })
        .where(eq(browserCredentials.generation, reserved.generation))
        .run();
      this.db
        .update(browserAuthority)
        .set({ phase: 'ready', operationId: null })
        .run();
      return { accountId: reserved.accountId, generation: reserved.generation };
    });
  }

  saveSettings(write: () => void): void {
    transaction(this.db, write);
  }

  create(input: CredentialInput): void {
    transaction(this.db, () => {
      const snapshot = this.requireAccount(input.readIdentity());
      if (
        input.expectedGeneration !== undefined &&
        input.expectedGeneration !== snapshot.generation
      )
        throw new AuthorizationChanged();
      this.db
        .delete(browserCredentials)
        .where(lte(browserCredentials.expiresAt, input.now))
        .run();
      this.db
        .insert(browserCredentials)
        .values({
          ...snapshot,
          scope: input.scope,
          digest: input.digest,
          kind: input.kind,
          expiresAt: input.expiresAt,
        })
        .run();
    });
  }

  isValid(input: CredentialLookup): boolean {
    return transaction(this.db, () => {
      const snapshot = this.requireAccount(input.readIdentity());
      const credential = this.db
        .select()
        .from(browserCredentials)
        .where(
          and(
            eq(browserCredentials.digest, input.digest),
            eq(browserCredentials.scope, input.scope),
            eq(browserCredentials.kind, 'session'),
          ),
        )
        .get();
      return Boolean(
        credential &&
        credential.expiresAt > input.now &&
        credential.generation === snapshot.generation &&
        credential.accountId === snapshot.accountId,
      );
    });
  }

  exchange(
    input: CredentialLookup & { sessionDigest: string; expiresAt: number },
  ): boolean {
    return transaction(this.db, () => {
      const snapshot = this.requireAccount(input.readIdentity());
      const credential = this.db
        .select()
        .from(browserCredentials)
        .where(
          and(
            eq(browserCredentials.digest, input.digest),
            eq(browserCredentials.scope, input.scope),
            eq(browserCredentials.kind, 'launch'),
          ),
        )
        .get();
      if (
        !credential ||
        credential.expiresAt <= input.now ||
        credential.generation !== snapshot.generation ||
        credential.accountId !== snapshot.accountId
      )
        return false;
      this.db
        .delete(browserCredentials)
        .where(eq(browserCredentials.digest, input.digest))
        .run();
      this.db
        .insert(browserCredentials)
        .values({
          ...snapshot,
          digest: input.sessionDigest,
          scope: input.scope,
          kind: 'session',
          expiresAt: input.expiresAt,
        })
        .run();
      return true;
    });
  }

  revoke(scope: string, digest: string): void {
    this.db
      .delete(browserCredentials)
      .where(
        and(
          eq(browserCredentials.scope, scope),
          eq(browserCredentials.digest, digest),
        ),
      )
      .run();
  }

  close(): void {
    closeDatabase(this.db);
  }
}
